  app.querySelector('#shadow-reset-case').onclick=()=>{shadowQuest.trials[id]=createShadowTrial(id);persist();renderShadow();app.querySelector('#shadow-reset-case').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
