  for(const [selector,key] of [['#dictionary-key','key'],['#dictionary-value','value']])app.querySelector(selector).onchange=e=>{s.selection[key]=e.target.value;s.checked=false;persist();};
  app.querySelectorAll('[data-dictionary-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.dictionaryAction;dictionaryQuest.trials[id]=stepDictionary(s,action,s.selection.key,s.selection.value);persist();renderDictionary();app.querySelector(`[data-dictionary-action="${action}"]`).focus();});
  app.querySelector('#dictionary-check').onclick=()=>{s.checked=true;persist();if(dictionaryComplete(dictionaryQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderDictionary();app.querySelector('#dictionary-check').focus();};
