  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);bezierQuest=createBezier();renderBezier();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-bezier-case]').forEach(b=>b.onclick=()=>{bezierQuest.selected=b.dataset.bezierCase;persist();renderBezier();app.querySelector(`[data-bezier-case="${bezierQuest.selected}"]`).focus();});
