  app.querySelectorAll('[data-view-target]').forEach(b=>b.onclick=()=>{const target=b.dataset.viewTarget,field=b.dataset.viewField;c.mapping[target]=field;c.checked=false;persist();renderStableView();app.querySelector(`[data-view-target="${target}"][data-view-field="${field}"]`).focus();});
  app.querySelector('#check-view').onclick=()=>{c.checked=true;persist();if(viewsComplete(viewsQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderStableView();app.querySelector('#check-view').focus();};
