  app.querySelectorAll('[data-captions-scene]').forEach(b=>b.onclick=()=>{captionsQuest.scene=b.dataset.captionsScene;persist();renderGameCaptions();app.querySelector(`[data-captions-scene="${captionsQuest.scene}"]`).focus();});
