  app.querySelectorAll('[data-strata-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.strataView;if(!state.visited.includes(state.view))state.visited.push(state.view);persist();renderStrata();app.querySelector(`[data-strata-view="${state.view}"]`).focus();});
