  app.querySelector('#check-agent').onclick=()=>{policy.tested=true;persist();if(agentComplete(policy)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderAgentMemory();app.querySelector('#check-agent').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
