  app.querySelectorAll('[data-coherence-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.coherenceAction;coherenceQuest.states[id]=coherenceStep(state,action);persist();if(coherenceComplete(coherenceQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderCoherence();(app.querySelector(`[data-coherence-action="${action}"]`)||app.querySelector('[data-coherence-action]')||app.querySelector('#retry-coherence')).focus();});
