  app.querySelectorAll('[data-block-pattern]').forEach(b=>b.onclick=()=>{blocksQuest.selected=b.dataset.blockPattern;persist();renderBlocks();app.querySelector(`[data-block-pattern="${blocksQuest.selected}"]`).focus();});
