  app.querySelectorAll('[data-pruning-action]').forEach(b=>b.onclick=()=>{pruningQuest.states[id]=pruningStep(state,b.dataset.pruningAction);persist();if(pruningComplete(pruningQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderPruning();(app.querySelector('[data-pruning-action]')||app.querySelector('#retry-pruning')).focus();});
