  app.querySelectorAll('[data-collision-setting]').forEach(select=>select.onchange=()=>{const field=select.dataset.collisionSetting;collisionQuest.states[id]=createCollision(field==='speed'?select.value:state.speed,field==='mode'?select.value:state.mode);persist();renderCollision();app.querySelector(`[data-collision-setting="${field}"]`).focus();});
  if(!done)app.querySelector('#step-collision').onclick=()=>{collisionQuest.states[id]=collisionStep(state);persist();if(collisionComplete(collisionQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderCollision();(app.querySelector('#step-collision')||app.querySelector('#retry-collision')).focus();};
  if(done)app.querySelector('#retry-collision').onclick=()=>{collisionQuest.states[id]=createCollision(state.speed,state.mode);persist();renderCollision();app.querySelector('#step-collision').focus();};
