  app.querySelectorAll('[data-transfer-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.transferAction,before=transfer.states[id];transfer.states[id]=stepTransaction(before,action);if(transfer.states[id].index>before.index)transfer.actions[id].push(action);writeDraft(active.id,transferDraft());if(Object.values(transfer.states).every(item=>item.status==='done')){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderTransfer();(app.querySelector(`[data-transfer-action="${action}"]`)||app.querySelector('[data-transfer-prediction]')||app.querySelector('#retry-transfer')).focus();});
