  const points=shape=>shape.map(([x,y])=>`${150+x*38},${190-y*38}`).join(' ');
  const pointText=shape=>shape.map(([x,y])=>`(${x}, ${y})`).join('、');
  const grid=Array.from({length:7},(_,i)=>{const x=36+i*38,y=38+i*38;return `<line x1="${x}" y1="0" x2="${x}" y2="260"/><line x1="0" y1="${y}" x2="320" y2="${y}"/>`;}).join('');
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">紋章の遺跡 <b>✦</b></span></div><section class="panel search-panel"><div class="panel-header"><div><span class="panel-kicker">THE TURNING EMBLEM</span><h2>光の印を動かす</h2></div></div>${draftMessage()}<p class="panel-description">右への移動と、格子の中心を軸にした左回り90度の回転をそれぞれ一度ずつ使います。二つの操作の順番を選び、二つの扉の紋章に合わせましょう。各試行は最初の印から始まります。</p><div class="scenario-selector" role="group" aria-label="扉の紋章">${Object.entries(transformTargets).map(([key,item])=>`<button data-emblem-target="${key}" aria-pressed="${id===key}">${item.name}${emblem.tested[key]&&transformMatches(emblem.sequences[key],key)?' ✓':''}</button>`).join('')}</div><svg class="emblem-map" viewBox="0 0 320 260" role="img" aria-label="格子上の三角形。目標の点は ${pointText(target)}。${emblem.tested[id]?'変換後':'最初'}の点は ${pointText(actual)}。"><g class="emblem-grid">${grid}</g><line class="emblem-axis" x1="0" y1="190" x2="320" y2="190"/><line class="emblem-axis" x1="150" y1="0" x2="150" y2="260"/><circle cx="150" cy="190" r="4" fill="#87672f"/><polygon class="emblem-target" points="${points(target)}"/><polygon class="emblem-actual" points="${points(actual)}"/></svg><p class="scenario-explanation">点線：扉の目標 ／ 緑：${emblem.tested[id]?'変換後':'最初'}の印 ／ 中央の点：回転の軸（原点）。右が x の正、上が y の正です。</p><p class="scenario-explanation">目標の頂点：${pointText(target)}<br>${emblem.tested[id]?'変換後':'最初'}の頂点：${pointText(actual)}</p><div class="join-choices">${emblem.sequences[id].map((choice,i)=>`<label>操作 ${i+1}<select data-transform="${i}">${Object.entries(transformOperations).map(([key,op])=>`<option value="${key}" ${key===choice?'selected':''}>${op.name}</option>`).join('')}</select><span>${transformOperations[choice].description}</span></label>`).join('')}</div><button class="primary execute" id="try-transform">最初の印に順番に使う <span>→</span></button>${emblem.tested[id]?`<div class="crystal-feedback" role="status"><strong>${correct?'紋章が重なりました！':'まだ目標と重なりません'}</strong><p>${correct?(complete?'二つの紋章が重なりました。':'もう一つの紋章も確かめましょう。'):'それぞれの操作は全ての頂点に作用します。順番を変えて試しましょう。'}</p></div>`:''}</section>${complete?`<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>二つの紋章が輝きました！</h2></div></div><p>移動してから回すと、移動した分も原点の周りに回ります。回してから移動すると、回した後の印全体が右へ動きます。この例では操作の順番を入れ替えると結果が異なります。</p><p>平行移動と回転は図形に使う変換の例です。ここでは２次元の三角形と固定された２操作を使いました。一般の行列、３次元変換や投影は扱っていません。</p>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">GIT-Rendering ↗</a>　｜　図形の移動と回転の一例です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);emblem=createTransform();renderTransform();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-emblem-target]').forEach(button=>button.onclick=()=>{emblem.selected=button.dataset.emblemTarget;writeDraft(active.id,emblem);renderTransform();app.querySelector(`[data-emblem-target="${emblem.selected}"]`).focus();});
  app.querySelectorAll('[data-transform]').forEach(select=>select.onchange=()=>{const i=Number(select.dataset.transform);emblem.sequences[id][i]=select.value;emblem.tested[id]=false;writeDraft(active.id,emblem);renderTransform();app.querySelector(`[data-transform="${i}"]`).focus();});
  app.querySelector('#try-transform').onclick=()=>{emblem.tested[id]=true;writeDraft(active.id,emblem);if(transformComplete(emblem)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderTransform();app.querySelector('#try-transform').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
